scripts.杀手死亡.txt:
// 杀手死亡后救出何梅

	Add($map039Enemy, 1);
	If ($map039Enemy == 4) @finished;
    Return;
    
@finished:
	FadeOut();
	DelNpc("吸血蝙蝠");
	DelNpc("大吸血蝙蝠");
	SaveNpc();
	SetPlayerPos(3, 40);
	SetPlayerDir(1);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 3, 41);
	SetNpcDir("张琳心", 2);
	SetNpcPos("何梅", 2, 41);
	SetNpcDir("何梅", 5);
	SetNpcRelation("张琳心", 2);
	SetNpcKind("张琳心", 3);
	SetNpcScript("何梅", "何梅对话.txt");
	Sleep(1000);
	ClearEffect();
	FadeIn();
	
	Sleep(500);
	Say("被掳的女子：你们，你们是谁……", 66);
	Say("独孤剑：姑娘不用害怕，我们是来救你的。", 1);
	Say("被掳的女子：你们……不是采花贼？", 66);
	Say("张琳心：难道还有女采花贼？", 21);
	Say("被掳的女子：可是那些贼人的首领，听嗓音就像是个女的……", 66);
	Say("张琳心：哦？这倒奇了，你见过他们的首领？", 21);
	Say("被掳的女子：没有见到，只是偷听过他们的谈话，其中提到要临安张大人交出什么“山河社稷图”来。", 66);
	Say("张琳心：真的和我父亲有关？不知道那“山河社稷图”是什么。", 24);
	Say("独孤剑：山河社稷图……他们还说了什么吗？", 1);
	Say("被掳的女子：我就知道这些了。", 66);
	Say("张琳心：那些贼人没有伤害你吧？",21);
	Say("被掳的女子：那倒没有。两位救命之恩，小女子没齿难忘。", 66);
	Say("张琳心：要谢就谢这位公子吧。是他救了我俩。其实我应该向姑娘说抱歉，因为那些人原本要抓的是我，结果连累了姑娘你。", 21);
	Say("被掳的女子：是这位公子吗？公子大恩大德，何梅万难报答，敢问恩人尊姓大名。", 66);
	Say("独孤剑：在下一介江湖武夫，贱名不足挂齿。", 1);
	Say("张琳心：他不说我说，姑娘，你这位救命大恩人复姓独孤，单名一个剑字。", 21);
	Say("何梅：原来是独孤大侠。", 66);
	Say("独孤剑：“大侠”二字决不敢当，两位姑娘，此地不宜久留，咱们还是尽快赶回临安去吧。", 1);
	Say("二女：好。", 109);
		
	FadeOut();
	Say("第二天，几人返回渔村。");
	StopMusic();
	PlayMusic("西山.mp3");
	LoadMap("map034_1_海边小渔村.map");
	LoadNpc("map034_1.npc");
	LoadObj("map034_1.obj");
	SetPlayerPos(27, 35);
	SetPlayerDir(7);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 27, 37);
	SetNpcDir("张琳心", 5);
	SetNpcKind("张琳心", 3);
	AddNpc("npc032_何梅.ini", 28, 36, 3);
	AddNpc("npc029_老王.ini", 31, 45, 3);
	FadeIn();
	
	Say("独孤剑：此地离临安不远，二位姑娘可以安心回家了。", 1);
	Say("何梅：独孤公子，你……你能送我回家吗，我……", 66);
	Say("张琳心：…… 帮人帮到底，送佛送到西，独孤公子，你就送何姑娘回家吧，。", 24);
	Say("独孤剑：这……好吧。", 1);
	Say("何梅：太好了！", 66);
	Say("张琳心：……", 24);
	Sleep(500);
	Say("张琳心：二位，我先走一步了，二位保重，<enter>……后会有期。", 24);	
	SetNpcKind("张琳心", 1);
	SetPlayerDir(2);
	NpcGoto("张琳心", 20, 38);
	DelNpc("张琳心");
	SaveNpc();
	Assign($Event, 170);

	PlayerGotoDir(2, 2);
	SetPlayerDir(2);
	Say("独孤剑：张姑娘……", 1);
	NpcGoto("何梅", 26, 33);
	SetNpcDir("何梅", 2);
	Say("何梅（害羞的）：独孤公子，我们……我们走吧。", 66);
	Say("独孤剑：姑娘稍候。", 1);
	SetNpcKind("何梅", 3);
	SetNpcRelation("何梅", 2);
	PlayerGoto(31, 44);
	SetPlayerDir(7);
    Say("老王：老汉还真没把你看出来，一个人就把这么多贼人都收拾掉，救回这几位姑娘，我这回算真是遇到一位少年英雄了，呵呵。", 65);
	Say("独孤剑：过奖了。老王，听说你当年吃过贾老实一只鸡蛋？", 2);
	Say("老王：不错。", 65);
	Say("独孤剑：那只鸡蛋是生的还是熟的？", 2);
	Say("老王：当然是熟的。", 65);
	Say("独孤剑：熟鸡蛋能不能孵出小鸡来？", 2);
	Say("老王：不能。", 65);	
	Say("独孤剑：那么你欠他什么？", 2);
	Say("老王：欠他什么？……，对啊，我欠他的不过是只熟鸡蛋，哈哈，哈哈，多谢公子指点。", 65);
	Say("老王：公子什么时候要船，我就什么时候出海。", 65);
	
	Assign($Event, 180);
	SetNpcScript("何梅", "何梅对话.txt");
	Memo("独孤剑和张琳心在秘道深处找到了被困的少女何梅，三人一起返回临安。");
	Memo("在海边小渔村，张琳心独自返回临安，在何梅的要求下，独孤剑送她回家。");
	Return;

